CREATE TYPE "IncidentSeverity" AS ENUM ('INFO','MINOR','MAJOR','CRITICAL');
CREATE TYPE "IncidentStatus" AS ENUM ('OPEN','INVESTIGATING','IDENTIFIED','MONITORING','RESOLVED','CLOSED');
CREATE TYPE "IncidentScope" AS ENUM ('PLATFORM','TENANT','SERVICE');
CREATE TABLE "Incident" ("id" TEXT NOT NULL,"title" TEXT NOT NULL,"description" TEXT NOT NULL,"severity" "IncidentSeverity" NOT NULL,"status" "IncidentStatus" NOT NULL DEFAULT 'OPEN',"scope" "IncidentScope" NOT NULL,"tenantId" TEXT,"components" JSONB NOT NULL DEFAULT '[]',"startedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"detectedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"acknowledgedAt" TIMESTAMP(3),"resolvedAt" TIMESTAMP(3),"cause" TEXT,"solution" TEXT,"ownerId" TEXT,"supportCaseId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Incident_pkey" PRIMARY KEY ("id"),CONSTRAINT "Incident_supportCase_fkey" FOREIGN KEY ("supportCaseId") REFERENCES "SupportCase"("id") ON DELETE SET NULL ON UPDATE CASCADE);
CREATE INDEX "Incident_tenantId_status_severity_idx" ON "Incident"("tenantId","status","severity");
CREATE INDEX "Incident_scope_status_idx" ON "Incident"("scope","status");
CREATE TABLE "IncidentEvent" ("id" TEXT NOT NULL,"incidentId" TEXT NOT NULL,"actorId" TEXT NOT NULL,"kind" TEXT NOT NULL,"body" TEXT NOT NULL,"internal" BOOLEAN NOT NULL DEFAULT false,"details" JSONB NOT NULL DEFAULT '{}',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "IncidentEvent_pkey" PRIMARY KEY ("id"),CONSTRAINT "IncidentEvent_incident_fkey" FOREIGN KEY ("incidentId") REFERENCES "Incident"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "IncidentEvent_incidentId_createdAt_idx" ON "IncidentEvent"("incidentId","createdAt");
CREATE TABLE "SlaPolicy" ("id" TEXT NOT NULL,"tenantId" TEXT NOT NULL,"severity" TEXT NOT NULL,"responseMinutes" INTEGER NOT NULL,"resolutionMinutes" INTEGER NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "SlaPolicy_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "SlaPolicy_tenantId_severity_key" ON "SlaPolicy"("tenantId","severity");
CREATE TABLE "OperationsMetric" ("id" TEXT NOT NULL,"tenantId" TEXT,"name" TEXT NOT NULL,"value" DOUBLE PRECISION NOT NULL,"windowMinutes" INTEGER NOT NULL,"recordedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"details" JSONB NOT NULL DEFAULT '{}',CONSTRAINT "OperationsMetric_pkey" PRIMARY KEY ("id"));
CREATE INDEX "OperationsMetric_tenantId_name_windowMinutes_recordedAt_idx" ON "OperationsMetric"("tenantId","name","windowMinutes","recordedAt");
